import * as core from './atlas-core.js'

const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))
const clone = value => JSON.parse(JSON.stringify(value))
const uid = () => crypto.randomUUID?.() || `atlas-${Date.now()}-${Math.random().toString(36).slice(2)}`
const nums = text => String(text).trim().split(/[\s,，;；|]+/).filter(Boolean).map(Number)
const integer = (value, fallback, min, max) => Number.isFinite(Number(value)) ? Math.max(min, Math.min(max, Math.trunc(Number(value)))) : fallback
const fmtDate = value => value && Number.isFinite(new Date(value).getTime()) ? new Date(value).toLocaleString('zh-CN', {hour12:false}) : '时间未提供'
const percent = value => Number.isFinite(value) ? `${(value * 100).toFixed(1)}%` : '—'
const button = (id, label, cls = '') => `<button type="button" class="atlas-button ${cls}" data-action="${esc(id)}">${esc(label)}</button>`
const notice = text => `<div class="atlas-notice at-notice">${esc(text)}</div>`
const empty = text => `<div class="at-empty">${esc(text)}</div>`
const field = (label, content) => `<label class="at-field"><span>${esc(label)}</span>${content}</label>`
const sample = ctx => {const football=ctx.source?.schemaId==='football',records=football?(ctx.snapshot?.events||[]):(ctx.records||[]);return `<div class="atlas-muted at-sample">来源：${esc(ctx.source?.label || ctx.source?.id || '未选择')} · 当前样本 ${records.length} ${football?'场':'期'} · ${esc(records[0]?.period||records[0]?.matchId||'—')} → ${esc(records.at(-1)?.period||records.at(-1)?.matchId||'—')}</div>`}
const shell = (ctx, title, text, body) => {ctx.el.innerHTML = `<section class="at-tool"><div class="at-title"><h2>${esc(title)}</h2><p>${esc(text)}</p></div>${sample(ctx)}${body}</section>`}
const table = (heads, rows) => `<div class="at-table-wrap"><table class="atlas-table at-table"><thead><tr>${heads.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.length ? rows.map(row=>`<tr>${row.map(cell=>`<td>${cell}</td>`).join('')}</tr>`).join('') : `<tr><td colspan="${heads.length}">${empty('当前范围没有记录')}</td></tr>`}</tbody></table></div>`
function on(ctx, selector, event, fn) {const el=ctx.el.querySelector(selector); if(el) el.addEventListener(event, async e=>{try{await fn(e)}catch(error){ctx.notify(error?.message || String(error))}})}
function actions(ctx, fns) {for(const [key,fn] of Object.entries(fns)) on(ctx,`[data-action="${key}"]`,'click',fn)}
async function persist(ctx, workspace) {if(new TextEncoder().encode(JSON.stringify(workspace)).length>250000)throw new Error('保存内容超过约250KB，请减少号码或历史记录。');await ctx.saveWorkspace(workspace);ctx.workspace=workspace}
function workspace(ctx) {const w=clone(ctx.workspace || {});w.presets ||= [];w.monitors ||= [];w.preferences ||= {};return w}
function formatNumbers(ctx, values) {const prefs=ctx.workspace?.preferences?.format || {};const sep=prefs.separator==='space'?' ':prefs.separator==='tab'?'\t':',';return values.map(n=>prefs.pad?String(n).padStart(2,'0'):String(n)).join(sep)}
async function copy(ctx,text) {try{await navigator.clipboard.writeText(text);ctx.notify('已复制')}catch{const area=document.createElement('textarea');area.value=text;area.style.position='fixed';area.style.left='-9999px';document.body.append(area);area.select();const ok=document.execCommand('copy');area.remove();if(!ok)throw new Error('浏览器不允许复制，请在文本框中手动复制。');ctx.notify('已复制')}}
function download(name,value,type='application/json') {const blob=new Blob([typeof value==='string'?value:JSON.stringify(value,null,2)],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
const keyOf = (values,rule) => core.numberKey ? core.numberKey(values,rule) : (rule?.ordered?values:[...values].sort((a,b)=>a-b)).join(',')
function validNumbers(values,rule,exact=true) {return Array.isArray(values)&&(!exact||values.length===rule.count)&&values.length>0&&values.every(n=>Number.isInteger(n)&&n>=rule.min&&n<=rule.max)&&(rule.replacement||new Set(values).size===values.length)}
function parseLines(text,rule) {const values=String(text).split(/\r?\n/).map(s=>s.trim()).filter(Boolean).map((s,i)=>{let v=nums(s);if(v.length===1&&rule.max<=9&&s.length===rule.count&&/^\d+$/.test(s))v=[...s].map(Number);if(!validNumbers(v,rule))throw new Error(`第${i+1}行号码不符合当前玩法（${rule.count}个，${rule.min}至${rule.max}${rule.replacement?'，允许重复':'，不可重复'}）。`);return v});const seen=new Set();return values.filter(v=>{const k=keyOf(v,rule);if(seen.has(k))return false;seen.add(k);return true}).slice(0,2001)}
function makePreset(ctx,name,extra={}) {return {id:uid(),name,sourceId:ctx.source.id,schemaId:ctx.source.schemaId,projection:ctx.projection || ctx.workspace?.preferences?.projection,zone:ctx.zone || ctx.workspace?.preferences?.zone,rule:clone(ctx.rule),rules:clone(ctx.rules||[]),options:{...clone(ctx.options||{}),...(extra.numbers?{inverse:false,globalTolerance:0}:{})},params:clone(ctx.params||{}),createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),...extra}}
async function savePreset(ctx,preset) {const w=workspace(ctx);if((preset.numbers?.length||0)>2000)throw new Error('每个显式号码方案最多保存2000组。');if(w.presets.length>=200&&!w.presets.some(p=>p.id===preset.id))throw new Error('方案数量已达200，请先整理旧方案');w.presets=[preset,...w.presets.filter(p=>p.id!==preset.id)];w.preferences.activePresetId=preset.id;await persist(ctx,w);ctx.notify(`已保存方案「${preset.name}」`);return preset}
function compatible(ctx,p) {return p&&p.sourceId===ctx.source?.id&&['min','max','count','ordered','replacement'].every(k=>p.rule?.[k]===ctx.rule?.[k])&&(!p.projection||!ctx.projection||p.projection===ctx.projection)&&(!p.zone||!ctx.zone||p.zone===ctx.zone)}
async function collect(ctx,opts={},max=2000) {const r=await ctx.getCandidates({...opts,page:1,pageSize:max,collectLimit:max});const seen=new Set(),items=(r.items||[]).filter(x=>{const key=x.key||keyOf(x.numbers,ctx.rule);if(seen.has(key))return false;seen.add(key);return true});const total=Number(r.count??r.total??items.length);return{items,total,complete:items.length>=total}}
async function presetMatcher(ctx,preset) {
  const rule=preset.rule||ctx.rule,positions=new Map(ctx.records.map((r,i)=>[r,i])),segmentStarts=[];let start=0;
  ctx.records.forEach((record,i)=>{if(record.previousContiguous===false)start=i;segmentStarts[i]=start});
  if(preset.matchMode==='draw-contained'||preset.matchMode==='group-contained'){const sets=(preset.numbers||[]).map(n=>new Set(n));return record=>preset.matchMode==='draw-contained'?sets.some(s=>record.numbers.every(n=>s.has(n))):sets.some(s=>[...s].every(n=>record.numbers.includes(n)))}
  const rules=preset.numbers?.length?[{id:'explicit-match',metricId:'numberSet',values:preset.numbers.map(n=>keyOf(n,rule)),enabled:true,minHits:1,maxHits:1}]:preset.rules||[];
  return(record,prev)=>{const index=positions.get(record)??0,result=core.matchesRules(record.numbers,rules,rule,{...(preset.numbers?{}:preset.options||{}),previous:record.previousContiguous!==false?prev?.numbers||null:null,params:preset.params||{},history:ctx.records.slice(segmentStarts[index]||0,index)});return result.known===false?null:result.accepted}
}
function withGaps(records,hits){return hits.flatMap((hit,i)=>records[i]?.previousContiguous===false?[null,hit]:[hit])}
function omission(hits){return core.omissionStats(hits)}
const missText=value=>value===null||value===undefined?'未知':String(value)
function * choose(values,k,start=0,prefix=[]) {if(!k){yield prefix;return}for(let i=start;i<=values.length-k;i++)yield*choose(values,k-1,i+1,[...prefix,values[i]])}
function chooseCount(n,k){let v=1;for(let i=1;i<=Math.min(k,n-k);i++)v=v*(n-i+1)/i;return Math.round(v)}

async function reconcileMonitor(ctx, monitor) {
  const before = JSON.stringify(monitor), records = ctx.records || [], indexes = new Map(records.map((r, i) => [r.period, i]));
  const match = await presetMatcher(ctx, monitor.preset), observedAt = new Date().toISOString();
  const oldCursor = monitor.lastSeenPeriod, oldMiss = monitor.currentMiss, previousLogs = (monitor.log || []).slice(0, 100);
  const added = new Set(), alerts = []; let corrected = false, reset = false;
  const logs = previousLogs.map(previous => {
    const entry = { ...previous }, index = indexes.get(entry.period);
    if (index === undefined) { entry.verification = 'outside-snapshot'; return entry; }
    const record = records[index], hit = match(record, records[index - 1]);
    if (JSON.stringify(entry.numbers) !== JSON.stringify(record.numbers) || entry.hit !== hit) {
      entry.originalNumbers ||= clone(entry.numbers || []);
      if (!Object.hasOwn(entry, 'originalHit')) entry.originalHit = entry.hit;
      entry.revisedAt = observedAt; corrected = true;
    }
    entry.numbers = clone(record.numbers); entry.hit = hit; entry.verification = 'current';
    entry.previousPeriod = records[index - 1]?.period || null; entry.previousContiguous = record.previousContiguous ?? null;
    return entry;
  });
  const cursor = indexes.get(oldCursor);
  if (monitor.running && cursor !== undefined) {
    for (let i = cursor + 1; i < records.length; i++) {
      const record = records[i];
      if (!logs.some(entry => entry.period === record.period)) {
        logs.unshift({ period: record.period, numbers: clone(record.numbers), hit: match(record, records[i - 1]), observedAt,
          previousPeriod: records[i - 1]?.period || null, previousContiguous: record.previousContiguous ?? null, verification: 'current' });
        added.add(record.period);
      }
      monitor.lastSeenPeriod = record.period;
    }
  } else if (monitor.running && records.length && oldCursor !== records.at(-1).period) {
    monitor.lastSeenPeriod = records.at(-1).period; reset = true;
    monitor.note = '上次观察期已不在当前样本内，已重设观察起点；中间过程不补记。';
  }
  monitor.log = logs.slice(0, 100);
  if (monitor.log.length) {
    const chronological = [...monitor.log].reverse(), first = chronological[0];
    const fromStart = !!monitor.startedAfter && first.previousPeriod === monitor.startedAfter;
    const fromLegacyCursor = previousLogs.length === 0 && first.previousPeriod === oldCursor;
    let miss = fromStart ? 0 : fromLegacyCursor ? oldMiss : null;
    let lowerBound = miss == null, previousPeriod = first.previousPeriod;
    for (const entry of chronological) {
      if (entry.verification !== 'current') { miss = null; lowerBound = true; previousPeriod = entry.period; continue; }
      if (entry.previousContiguous === false) { miss = 0; lowerBound = false; }
      else if (previousPeriod !== entry.previousPeriod) { miss = null; lowerBound = true; }
      if (entry.hit === null || entry.hit === undefined) { miss = null; lowerBound = true; }
      else if (entry.hit) { miss = 0; lowerBound = false; }
      else { miss = (miss ?? 0) + 1; }
      if (added.has(entry.period) && entry.hit === false && monitor.autoRemind && miss === Number(monitor.threshold)) {
        alerts.push(monitor.name + '：新到达记录连续' + (lowerBound ? '至少' : '') + miss + '次未匹配。');
      }
      previousPeriod = entry.period;
    }
    monitor.currentMiss = miss; monitor.currentMissLowerBound = miss !== null && lowerBound;
    if (!indexes.has(monitor.lastSeenPeriod)) { monitor.currentMiss = null; monitor.currentMissLowerBound = false; }
  }
  if (reset) { monitor.currentMiss = null; monitor.currentMissLowerBound = false; }
  if (corrected) monitor.recalculatedAt = observedAt;
  return { changed: before !== JSON.stringify(monitor), alerts };
}

async function renderMonitor(ctx) {
  const w=workspace(ctx);let changed=false,alerts=[]
  const pendingId=w.preferences.pendingMonitorPresetId;if(pendingId){const preset=w.presets.find(p=>p.id===pendingId);delete w.preferences.pendingMonitorPresetId;changed=true;if(preset&&compatible(ctx,preset)){const existing=w.monitors.findIndex(m=>m?.preset?.id===pendingId);if(existing<0){let slot=[0,1].find(i=>!w.monitors[i]||(!w.monitors[i].running&&!(w.monitors[i].preset?.numbers?.length||w.monitors[i].preset?.rules?.length)));if(slot===undefined)slot=[0,1].find(i=>!w.monitors[i]?.running);if(slot===undefined)alerts.push('两个监测槽都在运行，请先停止一个槽再载入方案。');else w.monitors[slot]={id:uid(),name:preset.name,sourceId:preset.sourceId,preset:clone(preset),running:false,threshold:3,autoRemind:false,log:[],currentMiss:0};}}else alerts.push('待载入方案与当前来源或范围不一致，请重新选择。')}
  for(const m of w.monitors.slice(0,2)){if(!m||m.sourceId!==ctx.source?.id||!compatible(ctx,m.preset))continue;const updated=await reconcileMonitor(ctx,m);changed ||= updated.changed;alerts.push(...updated.alerts)}
  if(changed)await persist(ctx,w)
  const cards=[0,1].map(i=>{const m=w.monitors[i];return `<div class="atlas-card"><h3>方案${i+1} ${m?`· ${esc(m.name)}`:''}</h3>${m?`<p class="atlas-muted">所属：${esc(m.preset?.sourceId||m.sourceId)} · ${esc(m.preset?.projection||'默认投影')} · ${esc(m.preset?.zone||'默认区')}${compatible(ctx,m.preset)?'':' · 与当前来源/范围不一致，请重新载入'}</p>`:''}<div class="at-actions">${button(`capture-${i}`,'使用当前条件')}${button(`paste-${i}`,'粘贴号码')}${button(`preset-${i}`,'载入已存方案')}</div><select class="atlas-select at-preset" data-slot="${i}"><option value="">选择已存方案</option>${w.presets.filter(p=>compatible(ctx,p)).map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select><textarea class="atlas-input at-textarea" data-slot-text="${i}" rows="4" ${m?.preset?.kind==='event-group'?'readonly':''} placeholder="每行一组号码，最多2000组">${esc(m?.preset?.numbers?.map(n=>formatNumbers(ctx,n)).join('\n')||'')}</textarea>${m?`<p>${esc(m.preset.numbers?`${m.preset.numbers.length}组${m.preset.kind==='event-group'?'组合事件（只读）':'明确号码'}`:`${m.preset.rules?.length||0}条条件`)} · <strong>${m.running?'正在观察':'已停止'}</strong> · 当前连续未匹配 ${m.currentMiss===null?'未知':(m.currentMissLowerBound?'≥':'')+integer(m.currentMiss,0,0,1000000)}</p><p class="atlas-muted">起点 ${esc(m.startedAfter||'未开始')} · ${esc(m.note||'只记录开始后新到达的期号')}</p>`:empty('选择当前条件、粘贴号码或载入方案后开始观察。')}<div class="at-inline">${field('提醒阈值',`<input class="atlas-input" type="number" min="1" max="1000" data-threshold="${i}" value="${integer(m?.threshold,3,1,1000)}">`)}<label><input type="checkbox" data-alert="${i}" ${m?.autoRemind?'checked':''}> 本页提醒</label></div><div class="at-actions">${button(`start-${i}`,'开始监测','primary')}${button(`stop-${i}`,'停止')}${button(`save-${i}`,'保存方案')}${button(`copy-${i}`,'复制号码')}${button(`submit-${i}`,'提交到条件')}${button(`clear-${i}`,'清除','danger')}</div>${table(['观察期号','号码','状态','首次观察 / 重算时间'],(m?.log||[]).slice(0,20).map(r=>[esc(r.period),esc(formatNumbers(ctx,r.numbers)),`<span class="at-${r.verification==='outside-snapshot'||r.hit===null?'unknown':r.hit?'hit':'miss'}">${r.verification==='outside-snapshot'?'当前快照外 / 未复核':r.hit===null?'未知 / 缺前序':r.hit?'匹配':'未匹配'}</span>${r.revisedAt?'<small> · 已按当前数据重算</small>':''}`,esc(fmtDate(r.observedAt))+(r.revisedAt?'<br><small>重算 '+esc(fmtDate(r.revisedAt))+'</small>':'' )]))}</div>`}).join('')
  shell(ctx,'双方案监测','最多同时观察两套方案；开始时排除已存在的历史记录。',`${notice('这是本机新到达数据的观察日志。导入或迟到的数据不构成开奖前预测证据；历史回看与真实预报分开。提醒只在本页打开时工作。页面统一检查数据库版本；历史更正会重算可回溯日志并保留首次观察时间，不生成新观察或重复提醒。快照外日志保留原观察值并标记未复核；遗漏带≥表示只能确认下界。缺期会中断连续段；依赖前序但无法计算的记录显示未知，不算未命中。本地导入的前序指相邻记录。')}<div class="at-grid">${cards}</div>`)
  async function update(i,fn){const next=workspace(ctx);while(next.monitors.length<i)next.monitors.push({id:uid(),name:'未配置方案',sourceId:ctx.source.id,preset:makePreset(ctx,'未配置方案'),running:false,threshold:3,autoRemind:false,log:[]});next.monitors[i]||={id:uid(),name:`观察方案${i+1}`,sourceId:ctx.source.id,preset:makePreset(ctx,`观察方案${i+1}`),running:false,threshold:3,autoRemind:false,log:[]};await fn(next.monitors[i],next);await persist(ctx,next);await ctx.reload()}
  for(let i=0;i<2;i++)actions(ctx,{
    [`capture-${i}`]:()=>update(i,m=>{m.preset=makePreset(ctx,`条件观察${i+1}`);m.name=m.preset.name;m.sourceId=ctx.source.id;m.running=false;m.log=[];m.currentMiss=0}),
    [`paste-${i}`]:async()=>{try{ctx.el.querySelector(`[data-slot-text="${i}"]`).value=await navigator.clipboard.readText()}catch{ctx.notify('请直接在号码框中粘贴，每行一组。')}},
    [`preset-${i}`]:()=>update(i,m=>{const id=ctx.el.querySelector(`[data-slot="${i}"]`).value,p=ctx.workspace.presets.find(x=>x.id===id);if(!p)throw new Error('先选择一个方案');m.preset=clone(p);m.name=p.name;m.sourceId=p.sourceId;m.running=false;m.log=[];m.currentMiss=0}),
    [`start-${i}`]:()=>update(i,m=>{if(!compatible(ctx,m.preset))throw new Error('此监测槽属于其他来源或范围，请使用当前条件或重新载入匹配方案');const text=ctx.el.querySelector(`[data-slot-text="${i}"]`).value.trim();if(text&&m.preset.kind!=='event-group'){const list=parseLines(text,ctx.rule);if(list.length>2000)throw new Error('最多2000组号码');m.preset=makePreset(ctx,`号码观察${i+1}`,{kind:'numbers',numbers:list,rules:[{id:uid(),metricId:'numberSet',values:list.map(n=>keyOf(n,ctx.rule)),enabled:true,minHits:1,maxHits:1}]});m.name=m.preset.name}if(!ctx.records?.length)throw new Error('先导入或加载历史数据以建立观察起点。');m.threshold=integer(ctx.el.querySelector(`[data-threshold="${i}"]`).value,3,1,1000);m.autoRemind=ctx.el.querySelector(`[data-alert="${i}"]`).checked;m.running=true;m.sourceId=ctx.source.id;m.startedAt=new Date().toISOString();m.startedAfter=ctx.records.at(-1).period;m.lastSeenPeriod=m.startedAfter;m.log=[];m.currentMiss=0;m.currentMissLowerBound=false;delete m.recalculatedAt;delete m.note}),
    [`stop-${i}`]:()=>update(i,m=>{m.running=false}),
    [`save-${i}`]:async()=>{const m=ctx.workspace.monitors?.[i];if(!m)throw new Error('先创建监测方案');await savePreset(ctx,{...clone(m.preset),id:uid(),name:m.name});},
    [`copy-${i}`]:async()=>{const m=ctx.workspace.monitors?.[i];if(!m)throw new Error('先创建监测方案');if(!compatible(ctx,m.preset))throw new Error('请先切换到该方案所属来源和范围');let list=m.preset.numbers;if(!list){const collected=await collect(ctx,{...m.preset.options,rules:m.preset.rules,params:m.preset.params,rule:m.preset.rule},2000);if(!collected.complete)throw new Error('候选超过2000组，请收窄条件再复制；可保存规则方案保留完整条件。');list=collected.items.map(x=>x.numbers)}await copy(ctx,list.map(n=>formatNumbers(ctx,n)).join('\n'))},
    [`submit-${i}`]:async()=>{const m=ctx.workspace.monitors?.[i];if(!m)throw new Error('先创建监测方案');if(!compatible(ctx,m.preset))throw new Error('请先切换到该方案所属来源和范围');if(m.preset.kind==='event-group'){await savePreset(ctx,{...clone(m.preset),id:uid()});ctx.notify('组合事件已保存，供监测与K线使用；不改变精确选号条件。');await ctx.navigate('presets')}else{if(!ctx.applyPreset)throw new Error('完整方案载入接口尚未就绪，请刷新页面');await ctx.applyPreset(clone(m.preset))}},
    [`clear-${i}`]:async()=>{const next=workspace(ctx);while(next.monitors.length<i)next.monitors.push({id:uid(),name:'未配置方案',sourceId:ctx.source.id,preset:makePreset(ctx,'未配置方案'),running:false,threshold:3,autoRemind:false,log:[]});next.monitors[i]={id:uid(),name:`观察方案${i+1}`,sourceId:ctx.source.id,preset:makePreset(ctx,`观察方案${i+1}`),running:false,threshold:3,autoRemind:false,log:[]};await persist(ctx,next);await ctx.reload()}
  })
  alerts.forEach(ctx.notify);return()=>{}
}

async function renderOmissions(ctx) {
  const viewState=ctx.viewState ||= {}, applied=viewState.omissions;
  let rows=[],kind='exact';shell(ctx,'遗漏分析','遗漏只描述当前样本中的未出现长度，不代表更接近下一次命中。',`${notice('从未命中的组合只知道遗漏至少达到已观察连续段长度，表中用“≥”标记。已知缺期会中断连续统计。组合数超过10000时要求缩小号码池，不把截断列表冒充全集。')}<div class="atlas-card"><div class="at-inline">${field('分析类型','<select class="atlas-select" id="at-om-kind"><option value="exact">当前玩法全集</option><option value="filtered">当前条件候选</option><option value="groups">2至10码组合</option></select>')}${field('组合大小','<input class="atlas-input" id="at-om-k" type="number" value="3" min="2" max="10">')}${field('号码池（组合模式）',`<input class="atlas-input" id="at-om-pool" value="${Array.from({length:ctx.rule.max-ctx.rule.min+1},(_,i)=>i+ctx.rule.min).join(',')}">`)}${field('排序','<select class="atlas-select" id="at-om-sort"><option value="currentMiss">当前遗漏</option><option value="maxMiss">最大遗漏</option><option value="count">出现次数</option></select>')}${button('om-run','查询','primary')}</div><p id="at-om-scope" class="atlas-muted">点击查询计算所选范围。</p><div id="at-om-table"></div><div class="at-inline">${field('起始序号','<input class="atlas-input" id="at-om-start" type="number" min="1" value="1">')}${field('结束序号','<input class="atlas-input" id="at-om-end" type="number" min="1" value="100">')}${button('om-copy','复制区间')}${button('om-save','保存区间方案')}${button('om-monitor','送入监测')}</div></div>`)
  const controls={kind:ctx.el.querySelector('#at-om-kind'),k:ctx.el.querySelector('#at-om-k'),pool:ctx.el.querySelector('#at-om-pool'),sort:ctx.el.querySelector('#at-om-sort'),start:ctx.el.querySelector('#at-om-start'),end:ctx.el.querySelector('#at-om-end')};
  const defaults={kind:'exact',k:3,pool:Array.from({length:ctx.rule.max-ctx.rule.min+1},(_,i)=>i+ctx.rule.min).join(','),sort:'currentMiss',start:1,end:100};
  for(const [key,input] of Object.entries(controls))input.value=String(applied?.[key]??defaults[key]);
  function selection(){if(!rows.length)throw new Error('先查询遗漏数据');const start=integer(ctx.el.querySelector('#at-om-start').value,1,1,rows.length),end=integer(ctx.el.querySelector('#at-om-end').value,100,start,rows.length);if(end-start+1>2000)throw new Error('每个方案最多2000组，请缩小区间');return rows.slice(start-1,end).map(x=>x.numbers)}
  function makeSelection(){const numbers=selection(),mode=kind==='groups'?(rows[0].numbers.length>=(ctx.records[0]?.numbers.length||ctx.rule.count)?'draw-contained':'group-contained'):'exact';return makePreset(ctx,`${kind==='groups'?'组合':'号码'}遗漏区间`,{kind:kind==='groups'?'event-group':'numbers',numbers,rules:kind==='groups'?[]:[{id:uid(),metricId:'numberSet',values:numbers.map(n=>keyOf(n,ctx.rule)),enabled:true,minHits:1,maxHits:1}],matchMode:mode})}
  const run=async()=>{if(!ctx.records?.length)throw new Error('当前没有历史样本');const query=Object.fromEntries(Object.entries(controls).map(([key,input])=>[key,input.value])),runKind=query.kind;let groups=[],scope='';
      if(runKind==='groups'){const pool=[...new Set(nums(query.pool))].sort((a,b)=>a-b),k=integer(query.k,3,2,10);if(pool.some(n=>!Number.isInteger(n)||n<ctx.rule.min||n>ctx.rule.max)||pool.length<k)throw new Error('号码池不合法或少于组合大小');const total=chooseCount(pool.length,k);if(total>10000)throw new Error(`共${total.toLocaleString()}组，请缩小号码池（上限10000组）`);groups=[...choose(pool,k)];scope=k>=(ctx.records[0]?.numbers.length||ctx.rule.count)?'命中定义：当期全部号码均包含在所选组合中。':'命中定义：所选组合的每个号码均出现在当期号码中。'}
      else if(runKind==='filtered'){const r=await collect(ctx,{},10000);if(!r.complete)throw new Error(`候选超过10000组（返回总数${r.total}），请收窄当前条件`);groups=r.items.map(x=>x.numbers);scope='只分析当前筛选候选，不是玩法全集。'}
      else{for(const n of core.enumerateCandidates(ctx.rule)){groups.push(n);if(groups.length>10000)throw new Error('玩法全集超过10000组，请使用当前条件候选或组合模式')}scope='当前投影/分区玩法全集；命中按完整号码与顺序规则判断。'}
      rows=groups.map(numbers=>{const set=new Set(numbers),key=keyOf(numbers,ctx.rule),rules=[{metricId:'numberSet',values:[key],minHits:1,maxHits:1}];const hits=ctx.records.map(r=>{if(runKind==='groups')return numbers.length>=r.numbers.length?r.numbers.every(n=>set.has(n)):numbers.every(n=>r.numbers.includes(n));const match=core.matchesRules(r.numbers,rules,ctx.rule);return match.known===false?null:match.accepted});return{numbers,...omission(withGaps(ctx.records,hits)),censored:!hits.some(Boolean)}});const sort=query.sort;rows.sort((a,b)=>b[sort]-a[sort]||keyOf(a.numbers,ctx.rule).localeCompare(keyOf(b.numbers,ctx.rule)));ctx.el.querySelector('#at-om-scope').textContent=`${rows.length}组 · ${ctx.records.length}期。${scope} 表格显示前300组，区间操作覆盖完整排序。`;ctx.el.querySelector('#at-om-table').innerHTML=table(['序号','号码组合','当前遗漏','最大遗漏','出现次数','最大连出'],rows.slice(0,300).map((r,i)=>[String(i+1),esc(formatNumbers(ctx,r.numbers)),`${r.censored&&r.currentMiss!==null?'≥':''}${missText(r.currentMiss)}`,`${r.censored?'≥':''}${r.maxMiss}`,String(r.count),String(r.maxStreak)]));kind=runKind;viewState.omissions={applied:true,...query};if(Object.entries(controls).every(([key,input])=>input.value===query[key]))ctx.markClean?.();};
  actions(ctx,{
    'om-run':run,

    'om-copy':()=>copy(ctx,selection().map(n=>formatNumbers(ctx,n)).join('\n')),
    'om-save':()=>savePreset(ctx,makeSelection()),
    'om-monitor':async()=>{const p=makeSelection();await savePreset(ctx,p);const next=workspace(ctx);next.monitors[0]={id:uid(),name:p.name,sourceId:ctx.source.id,preset:p,running:false,threshold:3,autoRemind:false,log:[]};await persist(ctx,next);await ctx.navigate('monitor')}
  })
  if(applied?.applied){try{await run()}catch(error){ctx.el.querySelector('#at-om-scope').textContent='已保留上次查询条件，当前数据无法计算：'+(error?.message||String(error));ctx.el.querySelector('#at-om-table').innerHTML=empty('等待当前来源的有效历史数据。')}}
}

function drawKline(host,hits,periods,bucket=10) {
  if(!hits.some(h=>h!==null&&h!==undefined)){host.innerHTML=empty('没有可计算的已知样本');return}
  let value=0,current=null;const candles=[];
  const flush=()=>{if(current){candles.push(current);current=null}};
  hits.forEach((hit,i)=>{if(hit===null||hit===undefined){flush();if(candles.length&&!candles.at(-1).gap)candles.push({gap:true});return}if(!current)current={open:value,high:value,low:value,close:value,from:periods[i],to:periods[i],n:0};value+=hit?1:-1;current.high=Math.max(current.high,value);current.low=Math.min(current.low,value);current.close=value;current.to=periods[i];current.n++;if(current.n>=bucket)flush()});flush();
  const list=candles.slice(-100),known=list.filter(c=>!c.gap),min=Math.min(0,...known.map(x=>x.low)),max=Math.max(1,...known.map(x=>x.high)),width=960,height=280,pad=30,step=(width-pad*2)/list.length;
  const y=n=>height-pad-(n-min)/(max-min||1)*(height-pad*2);
  host.innerHTML=`<svg class="at-chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="历史命中累计指标K线"><line x1="${pad}" x2="${width-pad}" y1="${y(0)}" y2="${y(0)}" stroke="#94a3b8" stroke-dasharray="4 4"/>${list.map((c,i)=>{const x=pad+(i+.5)*step;if(c.gap)return `<line x1="${x}" x2="${x}" y1="${pad}" y2="${height-pad}" stroke="#cbd5e1" stroke-dasharray="3 5"><title>缺期或未知：中断聚合，不增减累计值</title></line>`;const color=c.close>=c.open?'#059669':'#dc2626';return `<g><title>${esc(`${c.from}至${c.to} ${c.n}个已知样本 开${c.open} 高${c.high} 低${c.low} 收${c.close}`)}</title><line x1="${x}" x2="${x}" y1="${y(c.high)}" y2="${y(c.low)}" stroke="${color}"/><rect x="${x-Math.max(2,step*.3)}" y="${Math.min(y(c.open),y(c.close))}" width="${Math.max(4,step*.6)}" height="${Math.max(2,Math.abs(y(c.open)-y(c.close)))}" fill="${color}"/></g>`}).join('')}<text x="4" y="${pad}" fill="#64748b" font-size="12">${max}</text><text x="4" y="${height-pad}" fill="#64748b" font-size="12">${min}</text></svg><div class="atlas-muted">匹配 +1，未匹配 −1；每${bucket}个已知样本聚合，缺期或未知处中断。未知不计未匹配、不增减累计值。显示最近${known.length}根。</div>`
}
async function renderKline(ctx) {
  const viewState=ctx.viewState ||= {}, applied=viewState.kline;
  const presets=(ctx.workspace?.presets||[]).filter(p=>compatible(ctx,p)),entryPresetId=ctx.selectedPresetId||ctx.workspace?.preferences?.activePresetId||'';
  const selected=applied&&applied.entryPresetId===entryPresetId?applied.presetId:entryPresetId;
  shell(ctx,'历史命中K线','把规则或号码集的历史匹配结果变为累计指标，并按期数聚合。',`${notice('K线数值为“命中累计指标”，不是价格、资金或收益。历史选方案再画图属于回看，不算开奖前预测。已知缺期中断连续段；本地无日历来源的前序仅指相邻记录。')}<div class="atlas-card"><div class="at-inline">${field('方案',`<select class="atlas-select" id="at-kl-preset"><option value="">当前条件</option>${presets.map(p=>`<option value="${esc(p.id)}" ${p.id===selected?'selected':''}>${esc(p.name)}</option>`).join('')}</select>`)}${field('每根包含期数','<input class="atlas-input" id="at-kl-bucket" type="number" min="1" max="100" value="10">')}${button('kl-run','计算历史K线','primary')}${button('kl-export','导出序列')}</div><div id="at-kl-summary"></div><div id="at-kl-chart"></div><div id="at-kl-table"></div></div>`);
  ctx.el.querySelector('#at-kl-preset').value=presets.some(p=>p.id===selected)?selected:'';
  ctx.el.querySelector('#at-kl-bucket').value=String(integer(applied?.bucket,10,1,100));
  let result=[];
  const run=async()=>{const id=ctx.el.querySelector('#at-kl-preset').value,bucket=integer(ctx.el.querySelector('#at-kl-bucket').value,10,1,100),preset=presets.find(p=>p.id===id)||makePreset(ctx,'当前条件'),match=await presetMatcher(ctx,preset);result=ctx.records.map((r,i)=>({...r,hit:match(r,ctx.records[i-1])}));const hits=withGaps(result,result.map(r=>r.hit)),periods=result.flatMap(r=>r.previousContiguous===false?['缺期',r.period]:[r.period]),stat=omission(hits),unknown=result.filter(r=>r.hit===null).length;ctx.el.querySelector('#at-kl-summary').innerHTML=`<p>原始样本 ${result.length} · 已知 ${stat.observed} · 未知 ${unknown} · 匹配 ${stat.count} · 已知样本匹配率 ${percent(stat.count/stat.observed)} · 最大连匹配 ${stat.maxStreak} · 最大未匹配 ${stat.maxMiss}</p>`;drawKline(ctx.el.querySelector('#at-kl-chart'),hits,periods,bucket);ctx.el.querySelector('#at-kl-table').innerHTML=table(['期号','号码','历史匹配'],result.slice(-30).reverse().map(r=>[esc(r.period),esc(formatNumbers(ctx,r.numbers)),r.hit===null?'未知 / 缺前序':r.hit?'是':'否']));viewState.kline={presetId:id,bucket,entryPresetId};if(ctx.el.querySelector('#at-kl-preset').value===id&&integer(ctx.el.querySelector('#at-kl-bucket').value,10,1,100)===bucket)ctx.markClean?.()};
  actions(ctx,{'kl-run':run,'kl-export':()=>{if(!result.length)throw new Error('先计算序列');download('atlas-historical-match.json',{kind:'historical_match_not_forecast',sourceId:ctx.source.id,records:result})}});await run()
}
async function renderBanker(ctx) {
  if(ctx.rule.ordered||ctx.rule.replacement){shell(ctx,'胆拖工具','用于无序、不重复号码的组合玩法。',notice('当前玩法有位置或重复号码。请在顶部切换11选5、大乐透的前区或后区，再使用胆拖；不会把位置规则偷换为组合规则。'));return}
  const hot=Array.from({length:ctx.rule.max-ctx.rule.min+1},(_,i)=>i+ctx.rule.min).map(n=>({n,...omission(withGaps(ctx.records,ctx.records.map(r=>r.numbers.includes(n))))})).sort((a,b)=>b.count-a.count||a.n-b.n)
  shell(ctx,'胆拖与热胆统计',`当前区域每组${ctx.rule.count}个号码：固定全部胆码，从拖码中选够剩余位置。`,`${notice('热胆是样本内出现次数排行，不是未来概率。命中事件：当期号码中存在一组符合当前任选数量的组合，包含全部胆码，其余号码来自拖码；每期只计一次。不跨大乐透前后区混算。')}<div class="at-grid"><div class="atlas-card">${field('胆码',`<input class="atlas-input" id="at-bankers" placeholder="例如 ${ctx.rule.min}">`)}${field('拖码','<textarea class="atlas-input at-textarea" id="at-trailers" rows="3" placeholder="用逗号分隔，不与胆码重复"></textarea>')}<div class="at-actions">${button('bank-6','1拖6示例')}${button('bank-7','1拖7示例')}${button('bank-8','1拖8示例')}${button('bank-build','生成组合','primary')}</div><div id="at-bank-result"></div><div class="at-actions">${button('bank-copy','复制号码')}${button('bank-save','保存方案')}${button('bank-submit','提交到条件')}${button('bank-kline','历史K线')}</div></div><div class="atlas-card"><h3>号码出现统计</h3><p class="atlas-muted">每期同一号码只计一次。点击号码加入胆码。</p>${table(['号码','出现期数','当前遗漏','最大遗漏'],hot.map(r=>[`<button class="at-number" data-banker="${r.n}">${esc(String(r.n).padStart(ctx.rule.max>9?2:1,'0'))}</button>`,String(r.count),`${r.count?'':'≥'}${r.currentMiss}`,`${r.count?'':'≥'}${r.maxMiss}`]))}</div></div>`)
  let list=[],bankers=[],trailers=[]
  const generate=()=>{bankers=[...new Set(nums(ctx.el.querySelector('#at-bankers').value))];trailers=[...new Set(nums(ctx.el.querySelector('#at-trailers').value))];if(!bankers.length||bankers.length>=ctx.rule.count)throw new Error(`胆码须为1至${ctx.rule.count-1}个`);if([...bankers,...trailers].some(n=>!Number.isInteger(n)||n<ctx.rule.min||n>ctx.rule.max))throw new Error('号码超出当前范围');if(trailers.some(n=>bankers.includes(n)))throw new Error('胆码和拖码不能重合');const k=ctx.rule.count-bankers.length;if(trailers.length<k)throw new Error(`至少需要${k}个拖码`);const total=chooseCount(trailers.length,k);if(total>2000)throw new Error(`共${total.toLocaleString()}组，最多生成2000组，请缩小拖码`);list=[...choose(trailers,k)].map(t=>[...bankers,...t].sort((a,b)=>a-b));const keys=list.map(n=>keyOf(n,ctx.rule)),hits=ctx.records.map(r=>{const match=core.matchesRules(r.numbers,[{metricId:'numberSet',values:keys,minHits:1,maxHits:1}],ctx.rule);return match.known===false?null:match.accepted}),stat=omission(withGaps(ctx.records,hits));ctx.el.querySelector('#at-bank-result').innerHTML=`<p><strong>${list.length}组</strong> · 历史匹配 ${stat.count}/${stat.observed} · 当前未匹配 ${stat.currentMiss}</p><textarea class="atlas-input at-textarea" rows="8" readonly>${esc(list.map(n=>formatNumbers(ctx,n)).join('\n'))}</textarea>`}
  const preset=()=>{generate();return makePreset(ctx,`${bankers.length}胆${trailers.length}拖`,{numbers:list,rules:[{id:uid(),metricId:'numberSet',values:list.map(n=>keyOf(n,ctx.rule)),enabled:true,minHits:1,maxHits:1}],kind:'numbers'})}
  const handlers={'bank-build':generate,'bank-copy':async()=>{generate();await copy(ctx,list.map(n=>formatNumbers(ctx,n)).join('\n'))},'bank-save':()=>savePreset(ctx,preset()),'bank-submit':async()=>{const p=preset();if(!ctx.applyPreset)throw new Error('完整方案载入接口尚未就绪，请刷新页面');await ctx.applyPreset(p)},'bank-kline':async()=>{await savePreset(ctx,preset());await ctx.navigate('kline')}}
  for(const k of [6,7,8])handlers[`bank-${k}`]=()=>{const all=Array.from({length:ctx.rule.max-ctx.rule.min+1},(_,i)=>i+ctx.rule.min);if(all.length<k+1)throw new Error('当前区域号码不足，请手工输入');ctx.el.querySelector('#at-bankers').value=all[0];ctx.el.querySelector('#at-trailers').value=all.slice(1,k+1).join(',');generate();ctx.notify('仅按最小号码顺序填入示例，不是推荐号码。')}
  actions(ctx,handlers);ctx.el.querySelectorAll('[data-banker]').forEach(el=>el.addEventListener('click',()=>{const field=ctx.el.querySelector('#at-bankers'),values=new Set(nums(field.value));values.add(Number(el.dataset.banker));field.value=[...values].sort((a,b)=>a-b).join(',')}))
}

async function renderAssistant(ctx) {
  const questions=['这是什么玩法？','遗漏和热号代表什么？','如何保存、监测和回看方案？','当前样本有哪些特点？']
  shell(ctx,'本地知识助手','内置说明结合当前数据计算；本页不调用任何大模型或外部AI。',`<div class="atlas-card"><div class="at-actions">${questions.map((q,i)=>button(`faq-${i}`,q)).join('')}</div><div id="at-chat" class="at-chat"><div class="at-bubble">请选择一个问题。我会说明当前玩法、指标口径和可验证的样本事实。</div></div><div class="at-inline">${field('查找指标','<input class="atlas-input" id="at-assist-query" placeholder="输入：和值、跨度、AC、边邻、容错…">')}${button('faq-search','查找说明')}${button('faq-reset','重新提问')}<a class="atlas-button" href="/settings">现有AI配置中心</a></div></div>`)
  const answer=(question,text)=>{const chat=ctx.el.querySelector('#at-chat');chat.insertAdjacentHTML('beforeend',`<div class="at-bubble at-question">${esc(question)}</div><div class="at-bubble">${esc(text).replace(/\n/g,'<br>')}</div>`);chat.scrollTop=chat.scrollHeight}
  const replies=[()=>`当前来源是${ctx.source.label||ctx.source.id}，每期${ctx.rule.count}个号码，范围${ctx.rule.min}至${ctx.rule.max}，${ctx.rule.ordered?'保留位置顺序':'按无序组合处理'}，${ctx.rule.replacement?'允许重复':'不允许重复'}。当前选择的投影或区域独立计算。来源名称不等于官方彩票；奖金和销售规则请以对应官方公告为准。`,()=>`当前遗漏是从最近一期向前数，连续没有发生指定事件的样本期数；最大遗漏是窗口内最长未发生段。窗口内一次也没出现时只能报告“至少${ctx.records.length}期”。热号只是当前样本中出现较多的号码。随机独立序列不会因为久未出现而自动提高下一期概率。`,()=>`在条件页定义规则，保存方案后可送入双方案监测。开始监测时记录当前末期，只检查之后新到达的数据，页面关闭时暂停自动刷新。K线是现有样本回看的命中累计指标，匹配+1、未匹配−1，既不是金融价格，也不是开奖前证据。截图里的容错或复杂指标有歧义时，以本平台展示的公式版本为准。`,()=>{if(!ctx.records.length)return'当前没有数据。请在“数据与格式”导入数据，或选择已有开奖来源。';const count=new Map();for(const r of ctx.records)for(const n of new Set(r.numbers))count.set(n,(count.get(n)||0)+1);const sorted=[...count].sort((a,b)=>b[1]-a[1]).slice(0,5),sums=ctx.records.map(r=>r.numbers.reduce((a,b)=>a+b,0));return`现有${ctx.records.length}期：${ctx.records[0].period}至${ctx.records.at(-1).period}。\n样本内每期出现次数较多的号码：${sorted.map(([n,c])=>`${n}（${c}期）`).join('、')}。\n和值平均${(sums.reduce((a,b)=>a+b,0)/sums.length).toFixed(2)}，最小${Math.min(...sums)}，最大${Math.max(...sums)}。这些是描述性统计，不是下期推荐。`}]
  const handlers={'faq-reset':()=>{ctx.el.querySelector('#at-chat').innerHTML='<div class="at-bubble">已清空本页对话。请选择问题或搜索指标。</div>'},'faq-search':()=>{const q=ctx.el.querySelector('#at-assist-query').value.trim();if(!q)throw new Error('请输入指标名称');const matches=core.metricCatalog(ctx.rule,ctx.params).filter(m=>`${m.name||m.label||''} ${m.id} ${m.description||m.definition||''}`.includes(q)).slice(0,6);answer(q,matches.length?matches.map(m=>`${m.name||m.label||m.id}：${m.description||m.definition||m.formula||'请到条件编辑器查看参数和允许值。'}`).join('\n'):'没有找到完全匹配的指标。可尝试和值、跨度、合值、AC、间空、边邻或012路。')}};questions.forEach((q,i)=>handlers[`faq-${i}`]=()=>answer(q,replies[i]()));actions(ctx,handlers)
}

function safeWorkspace(value) {if(!value||typeof value!=='object'||Array.isArray(value))throw new Error('工作区JSON必须是对象');const raw=value.workspace||value;if(!Array.isArray(raw.presets)||!Array.isArray(raw.monitors)||!raw.preferences||typeof raw.preferences!=='object')throw new Error('缺少presets、monitors或preferences字段');if(raw.presets.length>200||raw.monitors.length>2)throw new Error('最多200个方案、2个监测槽');for(const p of raw.presets){if(!p||typeof p.name!=='string'||!Array.isArray(p.rules))throw new Error('方案结构无效');if(p.numbers&&(p.numbers.length>2000||!p.numbers.every(n=>Array.isArray(n)&&n.every(Number.isFinite))))throw new Error('方案号码无效或过多')}const result=clone(raw);for(const m of result.monitors){if(!m||typeof m!=='object')throw new Error('监测槽结构无效');if(!m.preset||typeof m.preset!=='object'||!Array.isArray(m.preset.rules))throw new Error('监测方案缺少完整条件');m.running=false;m.threshold=integer(m.threshold,3,1,1000);m.currentMiss=null;m.log=Array.isArray(m.log)?m.log.filter(r=>r&&Array.isArray(r.numbers)&&r.numbers.every(Number.isFinite)).slice(0,100):[]}return result}
async function renderSettings(ctx) {
  const numberRule=Number.isInteger(ctx.rule?.count)?ctx.rule:{min:0,max:9,count:3,ordered:true,replacement:true};
  const pref=ctx.workspace?.preferences||{},format=pref.format||{},pairs=ctx.params?.pairs||[],sourceId=ctx.source?.id||'local:digits3',localIds=['local:digits3','local:eleven5','local:dlt','local:football'];
  const examples={
    'local:digits3':{sourceId:'local:digits3',records:[{period:'example-001',numbers:[1,2,3],drawAt:'2026-09-01T12:00:00+08:00'}]},
    'local:eleven5':{sourceId:'local:eleven5',records:[{period:'example-001',numbers:[1,3,5,7,11],drawAt:'2026-09-01T12:00:00+08:00'}]},
    'local:dlt':{sourceId:'local:dlt',records:[{period:'example-001',zones:{front:[1,7,15,21,35],back:[2,12]},drawAt:'2026-09-01T12:00:00+08:00'}]},
    'local:football':{sourceId:'local:football',records:[{matchId:'example-match-001',kickoff:'2026-09-01T20:00:00+08:00',home:'示例主队',away:'示例客队',status:'finished',homeScore:2,awayScore:1}]}
  }
  shell(ctx,'数据、格式与共享接口','独立板块保存自己的方案和界面设置，通过有界API共享数据；不会替换旧平台功能。',`<div class="at-grid"><div class="atlas-card"><h3>输出格式和指标参数</h3><div class="at-inline">${field('号码分隔符',`<select class="atlas-select" id="at-format-sep"><option value="comma" ${format.separator==='comma'?'selected':''}>逗号</option><option value="space" ${format.separator==='space'?'selected':''}>空格</option><option value="tab" ${format.separator==='tab'?'selected':''}>制表符</option></select>`)}<label><input type="checkbox" id="at-format-pad" ${format.pad?'checked':''}> 两位补零</label></div>${field('跳位配对（位置从1开始）',`<input class="atlas-input" id="at-pairs" value="${esc(pairs.map(p=>`${p[0]+1}-${p[1]+1}`).join(','))}" placeholder="留空使用默认隔位配对">`)}<p class="atlas-muted">参数按数据源、投影和分区分别保存；足球不使用号码指标参数。留空使用默认隔位配对（两位玩法使用相邻位置）；填写时明确指定每一对位置。无序玩法先按号码升序，再按位置配对。不宣称复原了参考软件未公开的跳位算法。</p>${field('小号上界',`<input class="atlas-input" id="at-smallmax" type="number" value="${integer(ctx.params?.smallMax,Math.floor((numberRule.min+numberRule.max)/2),numberRule.min,numberRule.max)}" min="${numberRule.min}" max="${numberRule.max}">`)}<label><input type="checkbox" id="at-oneprime" ${ctx.params?.oneAsPrime!==false?'checked':''}> 将1计入业务“质”组（并非数学质数）</label><div class="at-actions">${button('settings-save','保存参数','primary')}${button('settings-export','导出工作区JSON')}${button('settings-export-data','导出当前数据')}</div></div><div class="atlas-card"><h3>恢复工作区</h3><p class="atlas-muted">只导入本板块方案、监测和偏好。恢复后监测一律停止，旧日志不算新观察。</p><input class="atlas-input" type="file" accept="application/json,.json" id="at-workspace-file"><textarea class="atlas-input at-textarea" id="at-workspace-json" rows="5" placeholder="粘贴导出的工作区JSON"></textarea><label><input type="checkbox" id="at-restore-confirm"> 替换本板块现有方案和偏好</label><div class="at-actions">${button('settings-import','恢复工作区')}</div></div></div><div class="atlas-card"><h3>本地数据导入</h3>${notice('以下示例数据仅示范格式。导入的是历史/本地记录，不能被标记为旧平台的实盘预测成绩。时间必须是毫秒时间戳或包含时区的ISO字符串。')}<div class="at-inline">${field('本地数据源',`<select class="atlas-select" id="at-import-source">${localIds.map(s=>`<option value="${s}" ${s===sourceId?'selected':''}>${s}</option>`).join('')}</select>`)}${button('data-example','填入格式示例')}<input class="atlas-input" type="file" accept="application/json,.json" id="at-data-file"></div><textarea class="atlas-input at-textarea" id="at-data-json" rows="8" placeholder="粘贴 { sourceId, records: [...] }"></textarea><div class="at-actions">${button('data-import','校验并导入','primary')}</div><pre class="at-code" id="at-import-status"></pre></div><div class="atlas-card"><h3>共享API契约</h3><p>同源本地服务沿用应用鉴权。外部模块通过规范化数据源ID、玩法和区域接入；显式区分数据记录、条件方案和观察日志。</p><pre class="at-code">${esc(`POST /api/atlas/import\nContent-Type: application/json\n${JSON.stringify(examples['local:digits3'],null,2)}\n\nGET /api/atlas/workspace\nPUT /api/atlas/workspace\n{ "presets": [], "monitors": [], "preferences": {} }\n\n工作区总量上限256KB。方案应保存规则或有界号码集，不保存无限枚举结果。`)}</pre></div>`)
  on(ctx,'#at-workspace-file','change',async e=>{const file=e.target.files[0];if(file){if(file.size>256000)throw new Error('工作区文件不能超过256KB');ctx.el.querySelector('#at-workspace-json').value=await file.text()}})
  on(ctx,'#at-data-file','change',async e=>{const file=e.target.files[0];if(file){if(file.size>4*1024*1024)throw new Error('导入文件过大，请分批导入（上限4MB）');ctx.el.querySelector('#at-data-json').value=await file.text()}})
  actions(ctx,{
    'settings-save':async()=>{const text=ctx.el.querySelector('#at-pairs').value.trim(),pairs=text?text.split(/[,，;；\s]+/).filter(Boolean).map(pair=>{const m=/^(\d+)-(\d+)$/.exec(pair);if(!m)throw new Error('跳位格式为1-3,2-4');const p=[Number(m[1])-1,Number(m[2])-1];if(Number.isInteger(ctx.rule?.count)&&(p[0]===p[1]||p.some(n=>n<0||n>=numberRule.count)))throw new Error(`位置须在1至${numberRule.count}之间且不相同`);return p}):[];if(text&&!pairs.length)throw new Error('请输入有效配对，例如1-3，或留空使用默认');const next=workspace(ctx);next.preferences.format={separator:ctx.el.querySelector('#at-format-sep').value,pad:ctx.el.querySelector('#at-format-pad').checked};if(Number.isInteger(ctx.rule?.count)){next.preferences.metricParamsByScope ||= {};next.preferences.metricParamsByScope[`${ctx.source.id}:${ctx.projection||''}:${ctx.zone||''}`]={...(ctx.params||{}),pairs,smallMax:integer(ctx.el.querySelector('#at-smallmax').value,Math.floor((numberRule.min+numberRule.max)/2),numberRule.min,numberRule.max),oneAsPrime:ctx.el.querySelector('#at-oneprime').checked};if(!text)delete next.preferences.metricParamsByScope[`${ctx.source.id}:${ctx.projection||''}:${ctx.zone||''}`].pairs;}await persist(ctx,next);ctx.notify('格式与指标参数已保存');await ctx.reload()},
    'settings-export':()=>download('atlas-workspace.json',{format:'atlas-workspace.v1',exportedAt:new Date().toISOString(),workspace:ctx.workspace}),
    'settings-import':async()=>{if(!ctx.el.querySelector('#at-restore-confirm').checked)throw new Error('请勾选替换确认；可先导出当前工作区');const next=safeWorkspace(JSON.parse(ctx.el.querySelector('#at-workspace-json').value));await persist(ctx,next);ctx.notify('已恢复工作区；监测处于停止状态');await ctx.reload()},
    'settings-export-data':()=>download(`atlas-data-${ctx.source.id.replace(/[^a-z0-9-]/gi,'-')}.json`,{sourceId:ctx.source.id,exportedAt:new Date().toISOString(),records:ctx.source.schemaId==='football'?(ctx.snapshot?.events||[]):(ctx.snapshot?.records||ctx.records),projection:ctx.projection,zone:ctx.zone}),
    'data-example':()=>{const id=ctx.el.querySelector('#at-import-source').value;ctx.el.querySelector('#at-data-json').value=JSON.stringify(examples[id],null,2);ctx.notify('已填入示例；不会自动提交')},
    'data-import':async()=>{const data=JSON.parse(ctx.el.querySelector('#at-data-json').value),source=ctx.el.querySelector('#at-import-source').value;if(Array.isArray(data))throw new Error('请使用{sourceId,records:[...]}对象');if(data.sourceId!==source)throw new Error('JSON里的sourceId须与选定本地数据源一致');if(!Array.isArray(data.records)||!data.records.length)throw new Error('records不能为空');const r=await fetch('/api/atlas/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}),body=await r.json();if(!r.ok||body.ok===false)throw new Error(body.error?.message||body.message||(typeof body.error==='string'?body.error:`导入失败(${r.status})`));ctx.el.querySelector('#at-import-status').textContent=JSON.stringify(body,null,2);ctx.notify('数据导入完成；切换至对应本地来源查看。');await ctx.reload()}
  })
  await renderScreenshotIndex(ctx)
}

async function renderScreenshotIndex(ctx) {
  const section=document.createElement('section');section.className='atlas-card at-review';section.innerHTML='<h3>77张参考截图审查索引</h3><p class="atlas-muted">按文件名逐张记录可辨识功能、观察和不确定项。截图是功能参考；未公开的算法以本平台明确列出的定义为准。</p><input class="atlas-input" id="at-index-query" placeholder="搜索文件名、功能、胆码、足球、未知公式…"><p class="atlas-muted" id="at-index-count">正在载入索引…</p><div id="at-index-list" class="at-index-list"></div>';ctx.el.querySelector('.at-tool').append(section);
  try{const response=await fetch('/static/atlas-screenshots.json');if(!response.ok)throw new Error('索引暂不可用');const index=await response.json(),entries=Array.isArray(index.entries)?index.entries:[];const draw=()=>{const query=section.querySelector('#at-index-query').value.trim().toLowerCase(),matches=entries.filter(entry=>`${entry.file} ${(entry.features||[]).join(' ')} ${entry.observations||''} ${(entry.uncertain||[]).join(' ')}`.toLowerCase().includes(query));section.querySelector('#at-index-count').textContent=`显示${matches.length}/${entries.length}张 · 不可识别${Number(index.unreadable)||0}张 · 完全重复${Number(index.identicalDuplicatePairs)||0}组`;section.querySelector('#at-index-list').innerHTML=matches.map(entry=>`<details><summary>${esc(entry.file)} · ${(entry.features||[]).length}项记录</summary><ul>${(entry.features||[]).map(text=>`<li>${esc(text)}</li>`).join('')}</ul><p>${esc(entry.observations||'')}</p>${entry.uncertain?.length?`<p><strong>不能推断：</strong>${entry.uncertain.map(esc).join('；')}</p>`:''}</details>`).join('')||empty('没有匹配项')};section.querySelector('#at-index-query').addEventListener('input',draw);draw()}catch(error){section.querySelector('#at-index-count').textContent=error?.message||'索引暂不可用'}
}

async function renderCalculator(ctx) {
  shell(ctx,'组合与成本计算','仅做算术预算，不推荐倍投、追损或承诺盈利。',`${notice('次数和倍数改变投入与风险，不会提高单注事件概率。下面不会用历史遗漏或模型置信度自动提高倍数。')}<div class="atlas-card"><div class="at-inline">${field('每期注数','<input class="atlas-input" id="at-calc-n" type="number" value="100" min="1" max="1000000">')}${field('每注金额','<input class="atlas-input" id="at-calc-unit" type="number" value="1" min="0.01" step="0.01">')}${field('期数','<input class="atlas-input" id="at-calc-periods" type="number" value="10" min="1" max="100">')}${field('每期倍数（逗号分隔；空白为全1）','<input class="atlas-input" id="at-calc-multipliers" placeholder="1,1,1,1">')}${field('总预算（可选）','<input class="atlas-input" id="at-calc-budget" type="number" min="0" placeholder="例如1000">')}${button('calc-run','计算','primary')}</div><div id="at-calc-result"></div></div>`)
  const run=()=>{const n=integer(ctx.el.querySelector('#at-calc-n').value,100,1,1000000),periods=integer(ctx.el.querySelector('#at-calc-periods').value,10,1,100),unit=Number(ctx.el.querySelector('#at-calc-unit').value),text=ctx.el.querySelector('#at-calc-multipliers').value.trim(),multipliers=text?nums(text):Array(periods).fill(1),budgetText=ctx.el.querySelector('#at-calc-budget').value,budget=budgetText===''?null:Number(budgetText);if(budget!==null&&(!Number.isFinite(budget)||budget<0))throw new Error('预算须为非负数字');if(!Number.isFinite(unit)||unit<=0||unit>1000000)throw new Error('每注金额须大于0且不超过1000000');if(multipliers.length!==periods||multipliers.some(n=>!Number.isFinite(n)||n<=0||n>1000000))throw new Error('倍数数量须与期数一致，且每个倍数大于0、不超过1000000');let cumulative=0;const rows=multipliers.map((m,i)=>{const cost=n*unit*m;cumulative+=cost;return[String(i+1),String(m),cost.toFixed(2),cumulative.toFixed(2),budget!==null&&cumulative>budget?'超过预算':'—']});ctx.el.querySelector('#at-calc-result').innerHTML=`<p class="at-total">总投入 ${cumulative.toFixed(2)}${budget!==null?` · 预算余额 ${(budget-cumulative).toFixed(2)}`:''}</p>${table(['期次','倍数','当期成本','累计成本','预算状态'],rows)}`};actions(ctx,{'calc-run':run});run()
}

async function renderSports(ctx) {
  const raw=ctx.snapshot?.events||[],events=Array.isArray(raw)?raw:[],finished=events.filter(e=>e.status==='finished'&&Number.isFinite(e.homeScore)&&Number.isFinite(e.awayScore));
  const views=[['wdl','胜平负'],['handicap','让球'],['half','半全场'],['goals','总进球'],['score','比分'],['mixed','混合'],['traditional','传统'],['intel','情报'],['omission','遗漏'],['kline','K线'],['live','直播']]
  shell(ctx,'足球数据工作区','只展示当前来源实际导入的赛事；由终场比分计算的结果属于赛后统计。',`${notice('没有赔率、半场比分或让球数时不会生成对应结果。所谓直播视图仅显示导入记录的最新状态，不提供视频、实时比分源或虚构赛况。')}<div class="at-actions at-tabs">${views.map(([key,label])=>button(`sport-${key}`,label)).join('')}${button('sports-refresh','刷新本地数据')}${button('sports-import','导入赛事')}</div><div id="at-sports-view" class="atlas-card"></div>`)
  const result=e=>e.homeScore>e.awayScore?'主胜':e.homeScore<e.awayScore?'客胜':'平局',scores=e=>`${e.homeScore}:${e.awayScore}`,kick=e=>fmtDate(e.kickoff),label=e=>`${e.home} / ${e.away}`
  const draw=view=>{const el=ctx.el.querySelector('#at-sports-view');if(!events.length){el.innerHTML=empty('当前来源没有导入赛事。请切换“本地足球”来源并导入赛事JSON；其他彩票样本不会伪装成足球数据。');return}
    if(view==='omission'){const sorted=finished.filter(e=>e.kickoff!=null&&Number.isFinite(new Date(e.kickoff).getTime())).sort((a,b)=>new Date(a.kickoff)-new Date(b.kickoff));el.innerHTML='<h3>已完赛事件序列遗漏</h3>'+notice('只统计有明确开赛时间的已完赛记录，并按开赛时间排序，赛事强弱与条件不同，不可当作同分布随机试验或下场预测。')+table(['赛果','出现次数','当前遗漏','最大遗漏'],['主胜','平局','客胜'].map(v=>{const s=omission(sorted.map(e=>result(e)===v));return[v,String(s.count),String(s.currentMiss),String(s.maxMiss)]}));return}
    if(view==='kline'){const sorted=finished.filter(e=>e.kickoff!=null&&Number.isFinite(new Date(e.kickoff).getTime())).sort((a,b)=>new Date(a.kickoff)-new Date(b.kickoff));el.innerHTML='<h3>主胜事件累计指标</h3>'+notice('主胜+1，其余赛果−1；不同赛事的历史结果序列，不代表价格、盈利或未来胜率。')+'<div id="at-sports-chart"></div>';drawKline(el.querySelector('#at-sports-chart'),sorted.map(e=>result(e)==='主胜'),sorted.map(e=>e.matchId),5);return}
    const chosen=view==='live'?events.filter(e=>e.status==='live'||e.status==='scheduled'):view==='intel'||view==='traditional'?events:finished;let extra='',headers=['比赛ID','开赛时间','主队 / 客队','状态'],data=[]
    if(view==='wdl'){headers.push('终场','赛果','赔率');data=chosen.map(e=>[scores(e),result(e),e.odds?JSON.stringify(e.odds):'未提供'])}
    if(view==='handicap'){headers.push('终场','让球数','让球赛果');data=chosen.map(e=>[scores(e),Number.isFinite(e.handicap)?e.handicap:'未提供',Number.isFinite(e.handicap)?(e.homeScore+e.handicap>e.awayScore?'主胜':e.homeScore+e.handicap<e.awayScore?'客胜':'平局'):'无法计算']);extra='让球以主队分数加让球数计算；必须有明确的导入值。'}
    if(view==='half'){headers.push('半场','终场','半全场');data=chosen.map(e=>{const known=Number.isFinite(e.halfHomeScore)&&Number.isFinite(e.halfAwayScore);return[known?`${e.halfHomeScore}:${e.halfAwayScore}`:'未提供',scores(e),known?`${result({...e,homeScore:e.halfHomeScore,awayScore:e.halfAwayScore})}/${result(e)}`:'无法计算']})}
    if(view==='goals'){headers.push('终场','总进球');data=chosen.map(e=>[scores(e),e.homeScore+e.awayScore])}
    if(view==='score'){headers.push('终场比分');data=chosen.map(e=>[scores(e)])}
    if(view==='mixed'){headers.push('赛果','比分','总进球');data=chosen.map(e=>[result(e),scores(e),e.homeScore+e.awayScore])}
    if(view==='traditional'){headers.push('记录内结果');data=chosen.map(e=>[e.status==='finished'&&Number.isFinite(e.homeScore)&&Number.isFinite(e.awayScore)?result(e):'未完赛']);extra='未导入传统14场/任选9场的正式期次与赛事清单，因此这里只整理真实赛事，不生成伪造投注单。'}
    if(view==='intel'){headers.push('比分字段');data=chosen.map(e=>[Number.isFinite(e.homeScore)&&Number.isFinite(e.awayScore)?scores(e):'未提供']);extra='情报仅含已导入的队名、时间、比赛状态和比分，无伤停、战绩或赔率来源时不会补写。'}
    if(view==='live'){headers.push('当前记录比分');data=chosen.map(e=>[Number.isFinite(e.homeScore)&&Number.isFinite(e.awayScore)?scores(e):'尚未提供']);extra='手动刷新可读取最新导入记录；这里没有连接即时赛事网络。同一比赛ID不能重复导入，当前接口按新增事件留档。'}
    el.innerHTML=`<h3>${esc(views.find(v=>v[0]===view)?.[1]||'赛事')} · ${chosen.length}条</h3>${extra?notice(extra):''}${table(headers,chosen.slice(0,300).map((e,i)=>[esc(e.matchId),esc(kick(e)),esc(label(e)),esc(e.status),...(data[i]||[]).map(esc)]))}`
  };const handlers={'sports-refresh':()=>ctx.reload(),'sports-import':()=>ctx.navigate('settings')};views.forEach(([key])=>handlers[`sport-${key}`]=()=>draw(key));actions(ctx,handlers);draw('wdl')
}

export async function renderTool(name,ctx) {
  if(!ctx?.el)throw new Error('缺少工具容器');ctx.records ||= [];ctx.workspace ||= {presets:[],monitors:[],preferences:{}};ctx.notify ||= ()=>{};
  const tools={monitor:renderMonitor,omissions:renderOmissions,kline:renderKline,banker:renderBanker,assistant:renderAssistant,settings:renderSettings,sports:renderSports,calculator:renderCalculator};
  if(!tools[name]){shell(ctx,'工具未找到','请从左侧选择工具。',empty(name));return}
  if(!Number.isInteger(ctx.rule?.count)&&!['sports','settings','calculator'].includes(name)){shell(ctx,'当前数据类型不适用','足球赛事使用专属视图。',button('open-sports','打开足球数据'));actions(ctx,{'open-sports':()=>ctx.navigate('sports')});return}
  try{return await tools[name](ctx)}catch(error){shell(ctx,'工具数据暂不可用',error?.message||String(error),`${notice('已保存的数据和旧平台功能不受影响。检查数据源、号码范围和方案后重试。')}${button('tool-retry','重试')}`);actions(ctx,{'tool-retry':()=>ctx.reload()})}
}